@import "tailwindcss";
@import "@fontsource-variable/geist";
@import "@fontsource-variable/bricolage-grotesque";

@source "./**/*.{ts,tsx}";

@theme {
  --font-sans: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --font-display: "Bricolage Grotesque Variable", "Geist Variable", sans-serif;
  --color-ink: #140e0c;
  --color-ink-raised: #241913;
  --color-ivory: #f6efe8;
  --color-muted: #d7c8ba;
  --color-coral: #e86b3c;
  --color-coral-hot: #f07d4e;
  --color-gold: #f3d2b0;
  --color-line: #3c2e28;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 4.75rem;
  background: var(--color-ink);
  color-scheme: dark;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--color-ink);
  color: var(--color-ivory);
  font-family: var(--font-sans);
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

html,
body {
  overflow-x: clip;
}

:where(a, button, input, summary):focus-visible {
  outline: 2px solid var(--color-gold);
  outline-offset: 3px;
}

::selection {
  background: var(--color-coral);
  color: var(--color-ink);
}

.skip-link {
  position: absolute;
  top: 0.75rem;
  left: 1rem;
  z-index: 60;
  transform: translateY(-160%);
  background: var(--color-gold);
  color: var(--color-ink);
  padding: 0.55rem 0.8rem;
  font-weight: 650;
  text-decoration: none;
}

.skip-link:focus {
  transform: none;
}

.section-anchor {
  scroll-margin-top: 4.75rem;
}

@keyframes hero-settle {
  from {
    transform: scale(1.06);
  }
  to {
    transform: scale(1);
  }
}

.hero-still {
  transform-origin: center 68%;
  animation: hero-settle 1.8s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.rise {
  animation: rise 0.75s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes still-swap {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.still-swap {
  animation: still-swap 0.45s ease both;
}

.still-frame img {
  transition: transform 0.8s ease;
}

.still-frame:hover img {
  transform: scale(1.025);
}

@keyframes reveal {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.reveal {
  animation: reveal 0.35s ease both;
}

.plus {
  position: relative;
  width: 14px;
  height: 14px;
  flex: none;
  transition: transform 0.2s ease;
}

.plus::before,
.plus::after {
  position: absolute;
  background: currentColor;
  content: "";
  border-radius: 1px;
}

.plus::before {
  top: 0;
  left: 6px;
  width: 2px;
  height: 14px;
}

.plus::after {
  top: 6px;
  left: 0;
  width: 14px;
  height: 2px;
}

.plus-open {
  transform: rotate(45deg);
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  .rise,
  .reveal,
  .hero-still,
  .still-swap {
    animation: none;
  }

  .plus,
  .still-frame img {
    transition: none;
  }

  .still-frame:hover img {
    transform: none;
  }
}

